// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address sender1, address sender2, uint256 amount1, uint256 amount2) public {
        vm.assume(sender1 != address(0));
        vm.assume(sender2 != address(0));
        vm.assume(sender1 != sender2);
        amount1 = bound(amount1, 0, (type(uint256).max / 2) - 1);
        amount2 = bound(amount2, 0, (type(uint256).max / 2) - 1);
        vm.deal(sender1, amount1 + 1 ether);
        vm.deal(sender2, amount2 + 1 ether);

        vm.prank(sender1);
        c.addToBalance{value: amount1}();
        vm.prank(sender2);
        c.addToBalance{value: amount2}();

        uint256 sumOfBalances = c.getBalance(sender1) + c.getBalance(sender2);
        uint256 contractBalance = address(c).balance;
        assertTrue(sumOfBalances == contractBalance, "invariant broken: sum of balances != contract balance");
    }
}
